136	    /**
137	     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
138	     */
139	    private final class CleaningVisitor implements NodeVisitor {
140	        private int numDiscarded = 0;
141	        private final Element root;
142	        private Element destination; // current element to append nodes to
143	
144	        private CleaningVisitor(Element root, Element destination) {
145	            this.root = root;
146	            this.destination = destination;
147	        }
148	
149	        @Override public void head(Node source, int depth) {
150	            if (source instanceof Element) {
151	                Element sourceEl = (Element) source;
152	
153	                if (safelist.isSafeTag(sourceEl.normalName())) { // safe, clone and copy safe attrs
154	                    ElementMeta meta = createSafeElement(sourceEl);
155	                    Element destChild = meta.el;
156	                    destination.appendChild(destChild);
157	
158	                    numDiscarded += meta.numAttribsDiscarded;
159	                    destination = destChild;
160	                } else if (source != root) { // not a safe tag, so don't add. don't count root against discarded.
161	                    numDiscarded++;
162	                }
163	            } else if (source instanceof TextNode) {
164	                TextNode sourceText = (TextNode) source;
165	                TextNode destText = new TextNode(sourceText.getWholeText());
166	                destination.appendChild(destText);
167	            } else if (source instanceof DataNode && safelist.isSafeTag(source.parent().normalName())) {
168	                DataNode sourceData = (DataNode) source;
169	                DataNode destData = new DataNode(sourceData.getWholeData());
170	                destination.appendChild(destData);
171	            } else { // else, we don't care about comments, xml proc instructions, etc
172	                numDiscarded++;
173	            }
174	        }
175	
176	        @Override public void tail(Node source, int depth) {
177	            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
178	                destination = destination.parent(); // would have descended, so pop destination stack
179	            }
180	        }
181	    }
182	
183	    private int copySafeNodes(Element source, Element dest) {
184	        CleaningVisitor cleaningVisitor = new CleaningVisitor(source, dest);
185	        cleaningVisitor.traverse(source);
186	        return cleaningVisitor.numDiscarded;
187	    }
188	
189	    private ElementMeta createSafeElement(Element sourceEl) {
190	        Element dest = sourceEl.shallowClone(); // reuses tag, clones attributes and preserves any user data
191	        String sourceTag = sourceEl.tagName();
192	        Attributes destAttrs = dest.attributes();
193	        dest.clearAttributes(); // clear all non-internal attributes, ready for safe copy
194	
195	        int numDiscarded = 0;
196	        Attributes sourceAttrs = sourceEl.attributes();
197	        for (Attribute sourceAttr : sourceAttrs) {
198	            if (safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr)) { // will keep this attr
199	                String key = sourceAttr.getKey();
200	                String value = sourceAttr.getValue();
201	
202	                if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
203	                    if (Safelist.multiValueUrlAttribute(key)) { // srcset etc: resolve each candidate independently
204	                        value = resolveCandidateUrls(sourceEl, value);
205	                    } else {
206	                        value = sourceEl.absUrl(key);
207	                        if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
208	                            value = sourceAttr.getValue();
209	                    }
210	                }
211	                Range.AttributeRange range = sourceAttrs.sourceRange(key);
212	                destAttrs.put(key, value);
213	                NodeInternals.attributeRange(destAttrs, key, range);
214	            } else
215	                numDiscarded++;
216	        }
217	
218	        Attributes enforcedAttrs = safelist.getEnforcedAttributes(sourceTag);
219	        // special case for <a href rel=nofollow>, only apply to external links:
220	        if (sourceEl.nameIs("a") && enforcedAttrs.get("rel").equals("nofollow")) {
221	            String href = sourceEl.absUrl("href");
222	            if (!href.isEmpty()) {
223	                try {
224	                    URL baseUrl = new URL(sourceEl.baseUri());
225	                    URL linkUrl = new URL(href);
226	                    String baseHost = baseUrl.getHost();
227	                    if (!baseHost.isEmpty() && baseHost.equalsIgnoreCase(linkUrl.getHost())) // same site, so don't set the nofollow
228	                        enforcedAttrs.remove("rel");
229	                } catch (MalformedURLException ignored) {}
230	            }
231	        }
232	
233	        // apply enforced attributes case-insensitively, so a preserved-case source attr is canonicalized to the enforced key
234	        for (Attribute enforcedAttr : enforcedAttrs) {
235	            destAttrs.removeIgnoreCase(enforcedAttr.getKey());
236	            destAttrs.put(enforcedAttr.getKey(), enforcedAttr.getValue());
237	        }
238	        dest.attributes().addAll(destAttrs); // re-attach, if removed in clear
239	        return new ElementMeta(dest, numDiscarded);
240	    }
241	
242	    private static boolean isHtmlWhitespace(char c) {
243	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
244	    }
245	
246	    /**
247	     Resolve each comma-separated candidate URL (e.g. in a {@code srcset} attribute) against the element's base URI,
248	     preserving the candidate descriptors and the original separators. Returns the source value untouched when none of
249	     the candidates changed, so that already-normalized output is stable on a second clean.
250	     */
251	    private String resolveCandidateUrls(Element sourceEl, String value) {
252	        String baseUri = sourceEl.baseUri();
253	        int len = value.length();
254	        StringBuilder out = null;
255	        int start = 0;
256	        for (int i = 0; i <= len; i++) {
257	            if (i != len && value.charAt(i) != ',') continue;
258	
259	            String segment = value.substring(start, i);
260	            int segLen = segment.length();
261	            int urlStart = 0;
262	            while (urlStart < segLen && isHtmlWhitespace(segment.charAt(urlStart))) urlStart++;
263	            int urlEnd = urlStart;
264	            while (urlEnd < segLen && !isHtmlWhitespace(segment.charAt(urlEnd))) urlEnd++;
265	
266	            boolean changed = false;
267	            if (urlEnd > urlStart) {
268	                String candidate = segment.substring(urlStart, urlEnd);
269	                String resolved = StringUtil.resolve(baseUri, candidate);
270	                if (resolved.isEmpty()) resolved = candidate; // mirror single-URL behavior: leave unresolvable as-is
271	                if (!resolved.equals(candidate)) {
272	                    changed = true;
273	                    if (out == null) {
274	                        out = new StringBuilder(len + 16);
275	                        out.append(value, 0, start); // everything before the first changed candidate, flushed once
276	                    }
277	                    out.append(segment, 0, urlStart).append(resolved).append(segment, urlEnd, segLen);
278	                }
279	            }
280	            if (!changed && out != null) out.append(segment);
281	            if (out != null && i < len) out.append(',');
282	
283	            start = i + 1;
284	        }
285	        return out == null ? value : out.toString();
286	    }
287	
288	    private static class ElementMeta {
289	        Element el;
290	        int numAttribsDiscarded;
291	
292	        ElementMeta(Element el, int numAttribsDiscarded) {
293	            this.el = el;
294	            this.numAttribsDiscarded = numAttribsDiscarded;
295	        }
296	    }
