mkdir -p /tmp/jsoup-probe && cat > /tmp/jsoup-probe/Probe.java <<'EOF'
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.*;

public class Probe {
    static int fails = 0;
    static void show(String name, Safelist sl, String in) {
        try {
            String out = Jsoup.clean(in, sl);
            String out2 = Jsoup.clean(out, sl);
            boolean idem = out.equals(out2);
            // re-parse selector check is done externally
            System.out.println("[" + (idem ? "ok " : "NON-IDEMPOTENT") + "] " + name);
            System.out.println("    in : " + in.replace("\n","\\n").replace("\t","\\t").replace("\r","\\r"));
            System.out.println("    out: " + out.replace("\n","\\n").replace("\t","\\t").replace("\r","\\r"));
            if (!idem) {
                System.out.println("    out2: " + out2.replace("\n","\\n").replace("\t","\\t").replace("\r","\\r"));
                fails++;
            }
        } catch (Exception e) {
            System.out.println("[EX] " + name + ": " + e);
            fails++;
        }
    }
    public static void main(String[] args) {
        Safelist sl = Safelist.none()
            .addTags("p","b","i","pre","code","textarea","table","tbody","thead","tr","td","th","br","div","span","a","ul","li","h1");

        show("rejected wrapper hoist", sl, "<font>foo <b>bar</b> baz</font>");
        show("nested rejected", sl, "<font><center><b>x</b></center></font>");
        show("script between safe", sl, "<p>a</p><script>alert(1)</script><p>b</p>");
        show("script wrapping safe element", sl, "<script><p>nope</p></script>");
        show("unknown wrapper around p", sl, "<custom><p>safe</p></custom>");
        show("event attr", sl, "<p onclick='alert(1)'>text</p>");
        show("pre whitespace+literal", sl, "<pre>  a\n\tb &lt; c  &amp;amp;</pre>");
        show("code whitespace", sl, "<code>x  y\tz&amp;amp;</code>");
        show("textarea rcdata", sl, "<textarea>a &amp; b\n  c<d</textarea>");
        show("entity once", sl, "<p>&amp;amp; &lt;img src=x&gt;</p>");
        show("unclosed p", sl, "<p>One<p>Two");
        show("unclosed b inline", sl, "<p>a <b>b <p>c</p>");
        show("malformed table", sl, "<table><tr><td>One<td>Two</tr><tr>Three</table>");
        show("block inline adjacent", sl, "<p>One</p>Two <b>three</b><p>Four</p>");
        show("div inside p (parser split)", sl, "<p>hello<div>world</div>");
        show("empty", sl, "");
        show("all rejected", sl, "<script>x</script><style>y</style>");
        show("malformed", sl, "</div></tr><<<>>><p>x");
        show("text-only none", Safelist.none(), "Hello <b>world</b> &amp; <  > \"quotes\"");
        show("whitespace only", sl, "   \n\t ");
        show("rejected element with trailing space", sl, "<p>a</p><font>x</font> <p>b</p>");
        show("nested pre in rejected", sl, "<div><pre>line1\nline2  x</pre></div>");
        show("table incomplete cells", sl, "<table><tr><td>a<tr><td>b</table>");
        show("textarea unclosed", sl, "<textarea>raw &amp; text <p>not parsed");

        // source doc non-mutation
        Document doc = Jsoup.parseBodyFragment("<p onclick='x()'>a</p><font>b</font>", "http://example.com/");
        String before = doc.body().html();
        Jsoup.clean(doc.body().html(), "http://example.com/", sl);
        String after = Jsoup.clean(before, sl); // placeholder
        System.out.println("[src unchanged] " + before.equals(doc.body().html()));
        if (!before.equals(doc.body().html())) fails++;

        System.out.println("\nFAILURES(flagged): " + fails);
    }
}
