import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.*;
import java.util.*;

public class Verify {
    static int fail = 0;
    static void check(boolean cond, String msg) {
        if (!cond) { fail++; System.out.println("FAIL: " + msg); }
    }
    static String esc(String s){return s.replace("\n","\\n").replace("\t","\\t");}
    public static void main(String[] args) {
        Safelist sl = Safelist.none()
            .addTags("p","b","i","pre","code","textarea","table","tbody","thead","tr","td","th","br","div","span","a","ul","ol","li","h1","img")
            .addAttributes(":all","id","class","title")
            .addAttributes("a","href").addAttributes("img","src","alt","srcset")
            .addProtocols("a","href","http","https","#").addProtocols("img","src","http","https")
            .addProtocols("img","srcset","http","https");

        // 1) no executable content resurfaces
        String[] xss = {
            "<script>alert(1)</script>",
            "<p onclick='x()'>a</p>",
            "<a href='javascript:alert(1)'>x</a>",
            "<a href='JaVaScRiPt:alert(1)'>x</a>",
            "<a href='java\tscript:alert(1)'>x</a>",
            "<a href='&#106;avascript:alert(1)'>x</a>",
            "<img src='javascript:alert(1)'>",
            "<img srcset='/a 1x, javascript:alert(1)'>",
            "<img srcset='javascript:alert(1) 1x'>",
            "<a href='java%73cript:alert(1)'>x</a>",
            "<a href='  javascript:alert(1)'>x</a>",
            "<a href='vbscript:msgbox(1)'>x</a>",
            "<a href='data:text/html,1'>x</a>",
            "<ScRiPt>x</ScRiPt><p>ok</p>",
            "<a href='javascript:alert(1)' onclick='y()'>x</a>",
        };
        for (String x : xss) {
            String out = Jsoup.clean(x, "https://example.com/", sl);
            String low = out.toLowerCase(Locale.ROOT);
            check(!low.contains("javascript:"), "js scheme in: " + x + " -> " + out);
            check(!low.contains("vbscript:"), "vbs in: " + x + " -> " + out);
            check(!low.contains("onclick"), "onclick in: " + x + " -> " + out);
            check(!low.contains("<script"), "script tag in: " + x + " -> " + out);
            // ensure safe text preserved
            if (x.contains(">x</a>")) check(out.contains(">x<") || out.contains(">x</a>"), "anchor text lost: " + out);
            if (x.contains("<p>ok</p>")) check(out.contains("ok"), "safe p lost: " + out);
        }

        // 2) idempotence + reparse selector equivalence over a battery
        String[] inputs = {
            "<p id=1>One</p>Two <b>three</b><p>Four</p>",
            "<p>a</p><font>x</font> <p>b</p>",
            "<div><p>a</p>tail</div>",
            "<font>foo <b>bar</b> baz</font>",
            "<font><center><b>x</b></center></font>",
            "<pre>  a\n\tb &lt; c  &amp;amp;</pre>",
            "<textarea>a &amp; b\n  c<d</textarea>",
            "<table><tr><td>One<td>Two</tr><tr>Three</table>",
            "<p>One<p>Two",
            "<a href='#x'>a</a><a href='https://e.com/'>b</a>",
            "<img src='https://e.com/a.png' alt='A' id=im>",
            "<h1>H</h1>text<table><tr><td>x</table>end",
            "<custom><p>safe</p></custom>",
        };
        for (String in : inputs) {
            String o1 = Jsoup.clean(in, sl);
            String o2 = Jsoup.clean(o1, sl);
            check(o1.equals(o2), "idempotence: " + esc(in) + "\n   o1=" + esc(o1) + "\n   o2=" + esc(o2));
            Document d1 = Jsoup.parseBodyFragment(o1), d2 = Jsoup.parseBodyFragment(o2);
            // selector equivalence
            for (String sel : new String[]{"p","b","pre","code","textarea","td","tr","table","a","img","h1","[id]"}) {
                String a = d1.select(sel).outerHtml().replaceAll("\\s+"," ");
                String b = d2.select(sel).outerHtml().replaceAll("\\s+"," ");
                check(a.equals(b), "selector " + sel + " differs for " + esc(in));
            }
            check(d1.text().equals(d2.text()), "visible text differs for " + esc(in) + " : ["+d1.text()+"] vs ["+d2.text()+"]");
        }

        // 3) source document not mutated (deep), and safelist reusable / independent
        String raw = "<p onclick='x()'>a</p><a href='/foo'>l</a><font>b</font><img srcset='/a 1x,/b 2x'>";
        Document dirty = Jsoup.parseBodyFragment(raw, "https://example.com/");
        String before = dirty.body().html();
        String c1 = new Cleaner(sl).clean(dirty).body().html();
        String c2 = new Cleaner(sl).clean(dirty).body().html();
        check(c1.equals(c2), "two cleans differ");
        check(before.equals(dirty.body().html()), "source doc mutated:\n before=" + before + "\n after =" + dirty.body().html());

        // 4) empty / all-rejected / malformed don't throw and are stable
        for (String in : new String[]{"", "   ", "<script>x</script><style>y</style>", "</div></tr><<<>>>", "\0\0\0"}) {
            try {
                String o1 = Jsoup.clean(in, sl);
                String o2 = Jsoup.clean(o1, sl);
                check(o1.equals(o2), "edge idempotence for [" + esc(in) + "] -> " + esc(o1) + " / " + esc(o2));
            } catch (Exception e) {
                check(false, "edge threw for [" + esc(in) + "]: " + e);
            }
        }

        System.out.println(fail == 0 ? "ALL VERIFY PASS" : ("VERIFY FAILURES=" + fail));
    }
}
