import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import java.util.Random;

public class Rnd {
    static String[] tags = {"div","p","b","i","span","ul","li","table","tr","td","h1","br","pre","code","a","img","section","em"};
    static Random r = new Random(42);
    static String gen(int depth) {
        StringBuilder sb = new StringBuilder();
        int n = r.nextInt(5);
        for (int k=0;k<n;k++){
            int choice = r.nextInt(10);
            if (choice < 6 && depth < 4) {
                String t = tags[r.nextInt(tags.length)];
                sb.append("<").append(t);
                if (r.nextBoolean()) sb.append(" id=x").append(r.nextInt(9));
                sb.append(">");
                if (t.equals("pre")||t.equals("code")) sb.append(" a\n  b\t c ");
                else sb.append(gen(depth+1));
                if (!t.equals("br") && !t.equals("img")) sb.append("</").append(t).append(">");
            } else if (choice < 8) {
                sb.append(r.nextBoolean()?"  txt ":"\nword ");
            } else {
                if (r.nextBoolean()) sb.append("<font>").append(gen(depth+1)).append("</font>");
                else sb.append("<script>bad()</script>");
            }
        }
        return sb.toString();
    }
    public static void main(String[] a){
        int drift=0, samples=20000;
        for (int s=0;s<samples;s++){
            String html = gen(0);
            Document d1 = Jsoup.parseBodyFragment(html);
            // test body.html stability (the inner-html path that was buggy)
            String h1 = d1.body().html();
            String h2 = Jsoup.parseBodyFragment(h1).body().html();
            if (!h1.equals(h2)) {
                drift++;
                if (drift<=10) System.out.println("DRIFT\n in="+html.replace("\n","\\n")+"\n h1="+h1.replace("\n","\\n")+"\n h2="+h2.replace("\n","\\n"));
            }
            // also outerHtml stability
            String o1 = d1.outerHtml();
            String o2 = Jsoup.parse(o1).outerHtml();
            if (!o1.equals(o2) ) { if(drift<=10) System.out.println("OUTER DRIFT for "+html.replace("\n","\\n")); drift++; }
        }
        System.out.println("samples="+samples+" drifts="+drift);
    }
}
