48	        assertEquals(expected, html);
49	        assertEquals(html, doc.outerHtml());
50	    }
51	
52	    @Test void sequentialTextNodesDontCollapse() {
53	        // tests that the pretty printer does not collapse (trim leading | trailing whitespace) when there are
54	        // sequential textnodes. That doesn't happen in a parse, but can when manipulated.
55	        Document doc = Jsoup.parse("<div><div></div>Hello</div>"); // needs to be text that would indent
