60	        assertEquals(" there.", ((TextNode) hello.nextSibling()).getWholeText());
61	
62	        assertEquals("Hello there.", div.text());
63	        assertEquals("<div></div>\nHello there.", div.html());
64	        assertEquals("<div>\n <div></div>\n Hello there.\n</div>", div.outerHtml());
